begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../helpers/legal-fixtures.inc
create function pg_temp.registration_user(p_lecturer boolean,p_verified boolean default false) returns uuid language plpgsql as $$
declare v uuid:=gen_random_uuid(); begin
  insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_user_meta_data,created_at,updated_at)
  values('00000000-0000-0000-0000-000000000000',v,'authenticated','authenticated',v::text||'@test.local',case when p_verified then now() else null end,
    jsonb_build_object('display_name','Registration test','role','admin','signup_kind',case when p_lecturer then 'lecturer' else 'student' end,'lecturer_application',jsonb_build_object('full_name','Dr. Registration Test','university','Adeleke University','faculty','Science','department','Computer Science','position','Lecturer','requested_courses','CSC 201','institutional_profile_url','https://example.edu/staff/test','verification_note','Staff directory reference')),now(),now());
  return v;
end $$;
create function pg_temp.login(p_user uuid) returns void language plpgsql as $$ begin
  perform set_config('request.jwt.claims',json_build_object('sub',p_user,'role','authenticated')::text,true);
  perform set_config('request.jwt.claim.sub',p_user::text,true);
  perform set_config('role','authenticated',true);
end $$;
select set_config('t.student',pg_temp.registration_user(false,true)::text,true) is not null;
select set_config('t.admin',pg_temp.registration_user(false,true)::text,true) is not null;
select set_config('t.applicant',pg_temp.registration_user(true,false)::text,true) is not null;
select set_config('t.other',pg_temp.registration_user(true,true)::text,true) is not null;
insert into public.user_roles(user_id,role) values(current_setting('t.admin')::uuid,'admin');
select set_config('t.application',(select id::text from public.lecturer_applications where user_id=current_setting('t.applicant')::uuid),true) is not null;
select is((select total from public.user_points where user_id=current_setting('t.student')::uuid),10::bigint,'student signup keeps 10 welcome XP');
select is((select count(*)::integer from public.user_roles where user_id=current_setting('t.student')::uuid and role='student'),1,'student registration keeps student role');
select is((select count(*)::integer from public.user_roles where user_id=current_setting('t.applicant')::uuid),0,'lecturer application receives no roles automatically');
select is((select total from public.user_points where user_id=current_setting('t.applicant')::uuid),0::bigint,'lecturer applicant receives no welcome XP');
select is((select count(*)::integer from public.points_ledger where user_id=current_setting('t.applicant')::uuid),0,'lecturer signup creates no welcome ledger entry');
select is((select count(*)::integer from public.enrollments where user_id=current_setting('t.applicant')::uuid),0,'lecturer applicant has no student courses');
select is((select registration_kind from public.profiles where id=current_setting('t.applicant')::uuid),'lecturer_applicant','registration intent persisted independently of mutable auth metadata');
select is((select leaderboard_visible from public.profiles where id=current_setting('t.applicant')::uuid),false,'applicants do not enter student leaderboard');
select throws_ok($$insert into public.user_roles(user_id,role) values(current_setting('t.applicant')::uuid,'lecturer')$$,'PT403','FORBIDDEN','even direct lecturer grants require an approved application');
select throws_ok($$insert into public.user_roles(user_id,role) values(current_setting('t.applicant')::uuid,'student')$$,'PT403','FORBIDDEN','applicants cannot acquire student role');
select throws_ok($$update public.profiles set registration_kind='student' where id=current_setting('t.applicant')::uuid$$,'PT403','FORBIDDEN','registration kind is immutable');
select pg_temp.login(current_setting('t.applicant')::uuid);
select is(public.get_my_profile_v1()->'roles','[]'::jsonb,'pending applicant can retrieve own base account without student role');
select is(public.get_my_lecturer_application_v1()->'application'->>'status','pending','applicant can read own status');
select is((public.get_my_lecturer_application_v1()->'application'->>'email_verified')::boolean,false,'email verification and admin approval are independent');
select throws_ok($$select * from public.lecturer_applications$$,'42501',null,'raw application table is not readable by clients');
select throws_ok($$select * from private.lecturer_application_reviews$$,'42501',null,'private review history is not directly readable');
select throws_ok($$select public.get_my_lecturer_courses_v1()$$,'PT403','FORBIDDEN','pending lecturer cannot load teaching courses');
select throws_ok($$select public.admin_list_lecturer_applications_v1()$$,'PT403','FORBIDDEN','applicant cannot inspect the review queue');
select throws_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'approved','','','{}',1,gen_random_uuid())$$,'PT403','FORBIDDEN','applicant cannot approve own application');
select throws_ok($$select public.resubmit_lecturer_application_v1('{}',1,gen_random_uuid())$$,'PT409','INVALID_STATE','pending application cannot be edited');
reset role;
update auth.users set raw_user_meta_data=raw_user_meta_data||'{"signup_kind":"student","role":"lecturer"}' where id=current_setting('t.applicant')::uuid;
select is((select count(*)::integer from public.user_roles where user_id=current_setting('t.applicant')::uuid),0,'changing metadata grants no roles');
select pg_temp.login(current_setting('t.admin')::uuid);
select ok((public.admin_list_lecturer_applications_v1()->>'pending_count')::integer>=2,'admin sees pending applications');
select throws_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'approved','','','{}',1,gen_random_uuid())$$,'PT403','FORBIDDEN','approval blocked until email confirmed');
select lives_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'changes_requested','Please provide your current staff directory reference.','Private reviewer note','{}',1,'12345678-1234-4234-8234-123456789001')$$,'admin can return an unverified application for corrections');
select is(public.admin_get_lecturer_application_v1(current_setting('t.application')::uuid)->'application'->'history'->0->>'internal_note','Private reviewer note','admin can read internal notes');
reset role;
update auth.users set email_confirmed_at=now() where id=current_setting('t.applicant')::uuid;
select pg_temp.login(current_setting('t.applicant')::uuid);
select ok(position('Private reviewer note' in public.get_my_lecturer_application_v1()::text)=0,'internal notes never appear in applicant payload');

select lives_ok($$select public.resubmit_lecturer_application_v1(public.get_my_lecturer_application_v1()->'application',2,'12345678-1234-4234-8234-123456789002')$$,'returned application can be corrected and resubmitted');
select lives_ok($$select public.resubmit_lecturer_application_v1('{}',2,'12345678-1234-4234-8234-123456789002')$$,'retry of completed resubmission is idempotent');
select is(public.get_my_lecturer_application_v1()->'application'->>'status','pending','correction returns application to pending');
reset role;
select pg_temp.login(current_setting('t.admin')::uuid);
select lives_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'approved','Welcome to the teaching team.','Verified independently.','{}',3,'12345678-1234-4234-8234-123456789003')$$,'verified application can be approved without course assignments');
select lives_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'approved','Welcome to the teaching team.','Verified independently.','{}',3,'12345678-1234-4234-8234-123456789003')$$,'repeat approval with same key is idempotent');
select throws_ok($$select public.admin_review_lecturer_application_v1(current_setting('t.application')::uuid,'rejected','Second reviewer decision.','','{}',3,gen_random_uuid())$$,'PT409','STALE_REVISION','stale concurrent review cannot overwrite approval');
reset role;
select is((select count(*)::integer from public.user_roles where user_id=current_setting('t.applicant')::uuid and role='lecturer'),1,'approval grants lecturer role exactly once');
select is((select count(*)::integer from public.user_roles where user_id=current_setting('t.applicant')::uuid and role='student'),0,'approval never grants student role');
select is((select total from public.user_points where user_id=current_setting('t.applicant')::uuid),0::bigint,'approval does not issue student XP');
select is((select count(*)::integer from public.notifications where user_id=current_setting('t.applicant')::uuid and kind='lecturer_application'),2,'review notifications are emitted once per decision');
select pg_temp.login(current_setting('t.applicant')::uuid);
select lives_ok($$select public.get_my_lecturer_courses_v1()$$,'approved lecturer can enter workspace with no courses');
select is(public.get_my_lecturer_courses_v1()->'items','[]'::jsonb,'approved lecturer initially has empty assignments');
select throws_ok($$select public.admin_assign_lecturer_courses_v1(current_setting('t.application')::uuid,'{}',4,gen_random_uuid())$$,'PT403','FORBIDDEN','lecturer cannot assign own teaching courses');
reset role;
select pg_temp.login(current_setting('t.other')::uuid);
select ok(public.get_my_lecturer_application_v1()->'application'->>'user_id'<>current_setting('t.applicant'),'applicant reads only their own application');
reset role;
select pg_temp.login(current_setting('t.admin')::uuid);
select throws_ok($$select public.admin_assign_lecturer_courses_v1(current_setting('t.application')::uuid,array['00000000-0000-0000-0000-000000000099'::uuid],4,gen_random_uuid())$$,'PT422','VALIDATION_FAILED','unknown course assignments are rejected');
select lives_ok($$select public.admin_assign_lecturer_courses_v1(current_setting('t.application')::uuid,'{}',4,'12345678-1234-4234-8234-123456789004')$$,'admin can manage assignments after approval');
select lives_ok($$select public.admin_assign_lecturer_courses_v1(current_setting('t.application')::uuid,'{}',4,'12345678-1234-4234-8234-123456789004')$$,'course assignment retry is idempotent');
reset role;
select lives_ok($$delete from auth.users where id=current_setting('t.applicant')::uuid$$,'new registration tables preserve full account erasure');
select is((select count(*)::integer from public.lecturer_applications where user_id=current_setting('t.applicant')::uuid),0,'account erasure removes the application');
set local role anon;
select is((select (feature_flags->>'lecturer_applications')::boolean from public.app_config where platform='web'),true,'public signup can detect deployment readiness');
select throws_ok($$select public.get_my_lecturer_application_v1()$$,'42501',null,'anonymous clients cannot inspect applications');
reset role;
select * from finish();
rollback;

